// Build the runner request {agent, event} from the "Run an agent" form (CONTRACT.md §1).
// The form text is DATA: it is only ever placed inside event.data.ask (a JSON string in the
// POST body) — never into a URL, a header, or SQL.
const AGENTS = ['media-investigator'];          // keep in step with the form's dropdown
const MAX_ASK = 8000;                            // whole event must stay well under 64 KiB
const MAX_SUBJECT = 200;

let f = {};
try { f = $('Agent Form').first().json || {}; } catch (e) { f = $input.first().json || {}; }
const pick = (...keys) => { for (const k of keys) if (f[k] !== undefined && f[k] !== null) return f[k]; return ''; };

const agent = String(pick('Agent', 'agent')).trim();
if (!AGENTS.includes(agent)) throw new Error(`Unknown agent "${agent}" (allowed: ${AGENTS.join(', ')})`);

const ask = String(pick('What should it look into?', 'ask')).trim().slice(0, MAX_ASK);
if (!ask) throw new Error('Nothing to look into: the ask is empty');

// subject is required by the contract; default to a neutral one when the form leaves it blank.
const subject = (String(pick('Subject (optional)', 'subject')).replace(/[\r\n\t]+/g, ' ').trim()
  || `manual:${agent}`).slice(0, MAX_SUBJECT);

// ULID-shaped id (Crockford base32: 10 chars of ms time + 16 random). Uniqueness only — not a
// secret, so Math.random is fine (the Code sandbox has no `crypto`). The runner dedupes on
// (event.id, agent), so a fresh id per submission means a fresh run.
const B32 = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
let t = Date.now(), time = '';
for (let i = 0; i < 10; i++) { time = B32[t % 32] + time; t = Math.floor(t / 32); }
let rand = '';
for (let i = 0; i < 16; i++) rand += B32[Math.floor(Math.random() * 32)];
const id = time + rand;

const event = {
  id,
  type: 'manual.investigate',
  source: 'matt',
  subject,
  dedupe_key: id,
  trust: 'internal',
  data: { ask },
};
return [{ json: { agent, event } }];

// Derive an IN-CLUSTER resume URL for the "Wait for Result" node and attach it as `callback`.
//
// $execution.resumeUrl is "<WEBHOOK_URL>webhook-waiting/<executionId>?signature=<resumeToken>".
// WEBHOOK_URL is the PUBLIC tunnel host, which only passes ^/webhook/inbound-mail.* — so we
// keep n8n's path + query (the signature IS the per-execution auth; n8n 2.x rejects a resume
// without it: 401 {"error":"Invalid token"}) and swap the origin for the webhook tier's
// in-cluster Service. Both the main and the webhook process serve /webhook-waiting/*
// (N8N_DISABLE_PRODUCTION_MAIN_PROCESS is unset); waiting executions are looked up in
// Postgres by id, so no activation/registration is involved and no webhook-tier roll is needed.
const CALLBACK_ORIGIN = 'http://n8n-webhook.n8n.svc.cluster.local:5678';

const resumeUrl = String($execution.resumeUrl || '');
const m = resumeUrl.match(/^https?:\/\/[^/]+(\/.*)$/);
if (!m) throw new Error(`Unexpected $execution.resumeUrl shape: "${resumeUrl}"`);
const pathAndQuery = m[1];

// Fail now, not 30 minutes from now: the URL must be /webhook-waiting/<this execution>?…signature=…
const shape = pathAndQuery.match(/^\/webhook-waiting\/([^/?#]+)\?(?:[^#]*&)?signature=[^&#]+/);
if (!shape) {
  throw new Error('resumeUrl is not "/webhook-waiting/<id>?signature=<token>" at the root of WEBHOOK_URL — '
    + 'n8n changed its resume-URL shape or WEBHOOK_URL gained a path; see docs/agent-sandbox-n8n.md');
}
if (String(shape[1]) !== String($execution.id)) {
  throw new Error(`resumeUrl execution id ${shape[1]} != $execution.id ${$execution.id}`);
}

const item = $input.first().json;
return [{ json: { ...item, callback: CALLBACK_ORIGIN + pathAndQuery } }];

// Normalise a runner callback (CONTRACT.md §3) into one agent_runs ledger row.
// Shared by agent-run-manual.json (input = the Wait node's webhook item) and agent-result.json
// (input = the Webhook item, possibly via Ensure Table). Everything in the body is DATA: it is
// clipped, type-checked, and later bound as ONE jsonb parameter — never concatenated into SQL.
const OUTCOMES = ['done', 'nothing_to_do', 'needs_human', 'failed'];
const EXIT_REASONS = ['completed', 'deadline', 'job_failed', 'no_result', 'invalid_result'];

let body = ($input.first().json || {}).body;
if (!body || typeof body !== 'object') {
  try { body = $('Result Webhook').first().json.body; } catch (e) { /* not the agent-result workflow */ }
}
if (!body || typeof body !== 'object') throw new Error('Callback has no JSON body');

const str = (v, n) => (typeof v === 'string' ? v : (v === undefined || v === null ? '' : String(v))).slice(0, n);
const ts = (v) => {
  if (v === undefined || v === null || v === '') return null;
  let d;
  if (typeof v === 'number') d = new Date(v < 1e12 ? v * 1000 : v);   // epoch seconds or ms
  else d = new Date(String(v));
  return isNaN(d.getTime()) ? null : d.toISOString();
};

const run_id = str(body.run_id, 128).trim();
if (!/^[A-Za-z0-9._:-]{1,128}$/.test(run_id)) throw new Error('Callback run_id missing or malformed');

const result = (body.result && typeof body.result === 'object') ? body.result : {};
const exit_reason = EXIT_REASONS.includes(body.exit_reason) ? body.exit_reason : str(body.exit_reason || 'unknown', 64);
const outcome = OUTCOMES.includes(result.outcome) ? result.outcome : 'failed';
const outputs = (Array.isArray(result.outputs) ? result.outputs : [])
  .filter(o => o && typeof o === 'object')
  .slice(0, 20)
  .map(o => ({ kind: str(o.kind, 64), title: str(o.title, 300), body: str(o.body, 32768) }));

// event type/subject are not in the callback; take them from this execution's Build Event when
// it exists (manual/Wait flow), else from body.event if the runner ever includes it, else null.
let ev = null;
try { ev = $('Build Event').first().json.event; } catch (e) { ev = (body.event && typeof body.event === 'object') ? body.event : null; }

return [{ json: {
  run_id,
  agent: str(body.agent, 64),
  event_id: str(body.event_id || (ev && ev.id), 128) || null,
  event_type: ev ? str(ev.type, 128) : null,
  subject: ev ? str(ev.subject, 200) : null,
  started: ts(body.started),
  finished: ts(body.finished),
  exit_reason,
  outcome,
  summary: str(result.summary, 2048),
  outputs,
} }];

// The Wait node resumed on its 30-minute limit, not on a callback. Its output is then its INPUT
// (the runner's 202 response), so we still know run_id. Record the give-up in the ledger so the
// run is visible; a late callback can no longer resume this execution (n8n answers 409), but the
// runner keeps its own record: GET /runs/<run_id>.
const r = $input.first().json || {};
const launched = (r.body && typeof r.body === 'object') ? r.body : {};
let ev = {}, agent = '';
try { const b = $('Build Event').first().json; ev = b.event || {}; agent = b.agent || ''; } catch (e) {}

const run_id = String(launched.run_id || '').slice(0, 128);
if (!run_id) throw new Error('Timed out, and the launch response had no run_id');

return [{ json: {
  run_id,
  agent,
  event_id: ev.id || null,
  event_type: ev.type || null,
  subject: ev.subject || null,
  started: null,
  finished: new Date().toISOString(),
  exit_reason: 'callback_timeout',
  outcome: 'failed',
  summary: 'No callback from agent-runner within 30 minutes. Check GET /runs/' + run_id
    + ' on the runner and the Job run-' + run_id + ' in namespace agents.',
  outputs: [],
} }];

// Build the ntfy push from the ledger row that was just written (Insert Ledger ... RETURNING).
// No row = duplicate callback (ON CONFLICT DO NOTHING) = no push.
// The push carries outcome + summary + report TITLE only; the report body stays in agent_runs.outputs.
const EMOJI = { done: 'white_check_mark', nothing_to_do: 'zzz', needs_human: 'raising_hand', failed: 'warning' };
const PRIO = { done: '3', nothing_to_do: '2', needs_human: '4', failed: '4' };

// Header values must be single-line ASCII; the full text goes in the body.
const header = (s, n) => String(s || '').replace(/[^\x20-\x7E]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);

const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.run_id) continue;
  let outputs = r.outputs;
  if (typeof outputs === 'string') { try { outputs = JSON.parse(outputs); } catch (e) { outputs = []; } }
  const report = (Array.isArray(outputs) ? outputs : []).find(o => o && o.kind === 'report');
  const reportTitle = report ? String(report.title || '') : '';
  const outcome = String(r.outcome || 'failed');

  const lines = [String(r.summary || '(no summary)').slice(0, 3000)];
  if (reportTitle) lines.push(`Report: ${reportTitle.slice(0, 300)}`);
  lines.push(`run ${r.run_id} · ${r.exit_reason || '?'}`);

  out.push({ json: {
    title: header(`${r.agent || 'agent'}: ${outcome}${reportTitle ? ' - ' + reportTitle : ''}`, 120),
    message: lines.join('\n'),
    tags: EMOJI[outcome] || 'robot',
    priority: PRIO[outcome] || '3',
  } });
}
return out;

// Turn the runner's answer to POST /runs into a push. Input is either the HTTP Request's full
// response ({statusCode, body}, neverError on) or its error output ({error}) when the runner was
// unreachable. In agent-run-manual.json only non-202 answers get here; in the async variant every
// answer does, and 202 means "launched, the result will arrive via agent-result".
const r = $input.first().json || {};
let agent = '', ev = {};
try { const b = $('Build Event').first().json; agent = b.agent || ''; ev = b.event || {}; } catch (e) {}

const code = Number(r.statusCode || 0);
const body = (r.body && typeof r.body === 'object') ? r.body : {};
const detail = String(typeof r.body === 'string' ? r.body : (body.error || body.detail || body.message || '')).slice(0, 300);
const WHY = {
  200: 'this event was already launched earlier; its result goes to the original requester',
  401: 'runner rejected the bearer token (check the agent-runner credential)',
  404: 'runner does not know this agent',
  422: 'runner rejected the manifest, event, or callback URL',
  429: 'daily run cap or cluster quota reached — try later',
  503: 'runner is paused (RUNNER_PAUSED=true)',
};

let title, message, tags = 'warning', priority = '4';
if (r.error) {
  const e = typeof r.error === 'object' ? (r.error.message || JSON.stringify(r.error)) : String(r.error);
  title = `${agent}: not started`;
  message = `Could not reach agent-runner: ${String(e).slice(0, 300)}`;
} else if (code === 202) {
  title = `${agent}: started`;
  message = `Run ${String(body.run_id || '?').slice(0, 128)} launched; the result will be pushed when it finishes.`;
  tags = 'hourglass_flowing_sand'; priority = '2';
} else {
  title = `${agent}: not started (HTTP ${code || '?'})`;
  message = (WHY[code] || 'unexpected runner response') + (detail ? `\n${detail}` : '');
}
message += `\nevent ${ev.id || '?'}`;
return [{ json: { title, message, tags, priority } }];
